#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    const char *input;
    size_t len;
    char norm[1025]; // enough for max length + null
    size_t n = 0;
    int palindrome = 1;

    if (argc <= 1) {
        // No input string – treat as empty string (palindrome)
        puts("PALINDROME");
        return 0;
    }

    input = argv[1];
    len = strlen(input);
    if (len > 1024) { // 0x400 bytes limit observed in the binary
        puts("TOO_LONG");
        return 0;
    }

    // Normalise: keep only alphanumeric characters, case‑insensitive (lowercase)
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            norm[n++] = (char)tolower(c);
        }
    }
    norm[n] = '\0';

    // Check palindrome on the normalised string
    for (size_t i = 0; i < n / 2; ++i) {
        if (norm[i] != norm[n - 1 - i]) {
            palindrome = 0;
            break;
        }
    }

    puts(palindrome ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
